    h, w = len(grid), len(grid[0])
    result = [row[:] for row in grid]

    for col in range(w):
        v_val = None
        v_rows = []
        for r in range(h):
            val = grid[r][col]
            if 0 < val < 10:
                if v_val is None:
                    v_val = val
                    v_rows = [r]
                elif val == v_val:
                    v_rows.append(r)
                else:
                    v_rows = []
                    v_val = None

        if len(v_rows) >= 2:
            best_row = None
            max_run = 0
            best_pattern = None

            for start_row in v_rows:
                pattern = [grid[start_row][c] for c in range(col + 1, w) if grid[start_row][c] != 0]
                if pattern:
                    run = max_consecutive_run(pattern)
                    if run > max_run:
                        max_run = run
                        best_row = start_row
                        best_pattern = pattern

            if best_pattern:
                for r in v_rows:
                    for i, pval in enumerate(best_pattern):
                        result[r][col + 1 + i] = pval
            return result

